import cv2
import numpy as np
from PIL import Image
import os

def apply_distance_key(input_path, output_path):
    print(f"Applying Distance Key to {input_path}...")
    
    img = Image.open(input_path).convert("RGBA")
    data = np.array(img).astype(np.float32)
    
    r, g, b, a = data[:,:,0], data[:,:,1], data[:,:,2], data[:,:,3]
    
    # The exact background color generated by the AI
    bg_r, bg_g, bg_b = 112.0, 254.0, 255.0
    
    # Calculate the color distance of every pixel from the background color
    dist = np.sqrt((r - bg_r)**2 + (g - bg_g)**2 + (b - bg_b)**2)
    
    # 1. DELETE ONLY THE PURE BACKGROUND
    # If the distance is very small (less than 15), it is undeniably the background.
    pure_bg_mask = dist < 15
    data[pure_bg_mask, 3] = 0
    
    # 2. ISOLATE THE BOUNDARY (The anti-aliasing)
    alpha = data[:, :, 3]
    kernel = np.ones((3,3), np.uint8)
    transparent_mask = (alpha == 0).astype(np.uint8)
    dilated_transparent = cv2.dilate(transparent_mask, kernel, iterations=1)
    boundary_mask = (alpha > 0) & (dilated_transparent == 1)
    
    # 3. DISTANCE MATTING ON THE BOUNDARY
    # We turn the distance directly into alpha. 
    # If a pixel is very close to the background color (dist=15), it should be almost transparent (Alpha=20).
    # If it is far (dist=100), it should be fully opaque (Alpha=255).
    # We map distance [15, 100] to Alpha [0, 255]
    dist_boundary = dist[boundary_mask]
    
    # Normalize the distance to a 0-255 scale
    # Map (dist - 15) to (0 - 255). Max out at 255.
    new_alpha = ((dist_boundary - 15) / 85.0) * 255.0
    new_alpha = np.clip(new_alpha, 0, 255)
    
    # Apply the new soft alpha
    alpha_flat = alpha[boundary_mask]
    alpha_flat = np.minimum(alpha_flat, new_alpha)
    alpha[boundary_mask] = alpha_flat
    data[:, :, 3] = alpha
    
    # 4. DESPILL THE EDGE
    # Suck out the cyan tint from the boundary so it matches the outline color
    g_flat = g[boundary_mask]
    b_flat = b[boundary_mask]
    r_flat = r[boundary_mask]
    
    g_flat = np.minimum(g_flat, r_flat)
    b_flat = np.minimum(b_flat, r_flat)
    
    g[boundary_mask] = g_flat
    b[boundary_mask] = b_flat
    
    data[:, :, 1] = g
    data[:, :, 2] = b
    
    # Save the result
    final_pil = Image.fromarray(data.astype(np.uint8))
    final_pil.save(output_path, "PNG")
    print(f"Saved to {output_path}")

def main():
    os.makedirs("../results/final_assets", exist_ok=True)
    apply_distance_key(
        "../results/batch_test/hands_test/hands_seed_6.png", 
        "../results/final_assets/cozy_girl_DISTANCE_6.png"
    )
    apply_distance_key(
        "../results/batch_test/hands_test/hands_seed_7.png", 
        "../results/final_assets/cozy_girl_DISTANCE_7.png"
    )
    print("\nDistance Matting complete!")

if __name__ == "__main__":
    main()
